def source(commit,path):return subprocess.check_output(['git','show',commit+':'+path],cwd=ROOT)
def controls(events,wake_mode=True,drop_raw_go=False):
    rg=0;drain=0;wake=0;rows=[]
    for cycle,e in enumerate(events):
        reset=e.get('reset',False);go=int(e.get('go',False));busy=int(e.get('walk_busy',False))
        leaf=1 if reset else wake if wake_mode else int(go or rg or busy or drain)
        rows.append(dict(cycle=cycle,reset=reset,go=go,go_e=rg,walk_busy=busy,drain_before=drain,leaf_edge=leaf,root_edge=1,go_consumed=bool(rg and leaf and not reset),missed_go=bool(rg and not leaf and not reset),x_capture_edge=1 if wake_mode else leaf))
        next_wake=1 if reset else int((go and not drop_raw_go) or rg or busy or drain)
        next_drain=0 if reset else 127 if rg or busy else max(0,drain-1)
        rg=0 if reset else go;wake=next_wake;drain=next_drain
    return rows

