    scenarios={'empty_go':[{}]*3+[{'go':True}]+[{}]*135,'work':[{}]*3+[{'go':True}]+[{}]+[{'walk_busy':True}]*10+[{}]*135,'reset_cancel':[{}]*3+[{'go':True}]+[{'walk_busy':True}]*3+[{'reset':True}]+[{}]*4+[{'go':True}]+[{}]*135}
